diff --git a/demos/low-latency-llama/utils.cuh b/demos/low-latency-llama/utils.cuh
index ae0d084..050b808 100644
--- a/demos/low-latency-llama/utils.cuh
+++ b/demos/low-latency-llama/utils.cuh
@@ -11,7 +11,39 @@ rms_norm(const sv_t &rms_scale_smem, const sv_t &activations_smem,
     if constexpr (Config::FP64_RMS) kittens::warp::sync();
     kittens::warp::load(activations_vec, activations_smem);
     float variance;
-    if constexpr (Config::FP64_RMS) {
+    if constexpr (Config::MATCH_TORCH_BF16_RMS && Config::NUM_CONSUMER_WARPS == 16 && !Config::FP64_RMS) {
+        // Match the installed PyTorch contiguous 2048-element FP32 mean:
+        // 512 threads, four adjacent values/thread, block tree then warp tree.
+        // Output scratch is unused until consumers finish RMS normalization.
+        auto *partials = reinterpret_cast<float *>(static_cast<char *>(scratch_memory) - 3 * 64 * Config::NUM_CONSUMER_WARPS);
+        const int tid = kittens::warpid() * 32 + kittens::laneid();
+        float partial = 0.f;
+        #pragma unroll
+        for (int j = 0; j < 4; ++j) {
+            const float value = static_cast<float>(activations_smem[kittens::laneid() * 4 + j]);
+            partial = __fadd_rn(partial, __fmul_rn(value, value));
+        }
+        partials[tid] = partial;
+        kittens::group<Config::NUM_CONSUMER_WARPS>::sync(0);
+        #pragma unroll
+        for (int offset = 256; offset >= 32; offset /= 2) {
+            if (tid < offset) {
+                partial = __fadd_rn(partial, partials[tid + offset]);
+                partials[tid] = partial;
+            }
+            kittens::group<Config::NUM_CONSUMER_WARPS>::sync(0);
+        }
+        if (kittens::warpid() == 0) {
+            #pragma unroll
+            for (int offset = 16; offset > 0; offset /= 2)
+                partial = __fadd_rn(partial, __shfl_down_sync(0xffffffff, partial, offset));
+            if (kittens::laneid() == 0) partials[0] = partial / 2048.f;
+        }
+        kittens::group<Config::NUM_CONSUMER_WARPS>::sync(0);
+        variance = partials[0];
+        // Every reader must finish before output scratch can be reused.
+        kittens::group<Config::NUM_CONSUMER_WARPS>::sync(0);
+    } else if constexpr (Config::FP64_RMS) {
         static_assert(offsetof(megakernel::instruction_state_t<Config>, scratch) % alignof(double) == 0);
         double partial = 0.;
         for (int i = kittens::laneid(); i < sv_t::length; i += 32) {
